/**
 * RocketChat Node - Version 1
 * Discriminator: resource=subscriptions, operation=read
 */


interface Credentials {
  rocketchatApi: CredentialReference;
}

/** Mark the subscription as read */
export type RocketchatV1SubscriptionsReadParams = {
  resource: 'subscriptions';
  operation: 'read';
/**
 * The room identifier
 */
    roomId: string | Expression<string>;
};

export type RocketchatV1SubscriptionsReadNode = {
  type: 'n8n-nodes-base.rocketchat';
  version: 1;
  config: NodeConfig<RocketchatV1SubscriptionsReadParams> & { credentials?: Credentials };
};